import { expect, test } from "../../fixtures";

test("the vendor with an unreadable insurance expiry is listed above the other", { tag: "@UI-09" }, async ({ pages, signIn, factory }) => {
  // Arrange
  const unreadable = await factory.vendorInReview({
    files: { insurance_certificate: "insurance_certificate_unparseable.txt" },
  });
  const readable = await factory.vendorInReview();
  await signIn("reviewer");

  // Act
  await pages.reviewQueue.goto();
  await expect(pages.reviewQueue.heading).toBeVisible();
  await expect(pages.reviewQueue.card(unreadable.vendor.name)).toBeVisible();
  await expect(pages.reviewQueue.card(readable.vendor.name)).toBeVisible();

  // Assert
  const upper = await pages.reviewQueue.card(unreadable.vendor.name).boundingBox();
  const lower = await pages.reviewQueue.card(readable.vendor.name).boundingBox();
  expect(upper, "unreadable vendor card has a layout box").not.toBeNull();
  expect(lower, "readable vendor card has a layout box").not.toBeNull();
  expect(upper!.y, "unreadable-date vendor is listed above the other").toBeLessThan(lower!.y);
});
